  "theme.group.surfaces": "Surfaces",
  "theme.group.surfaces.help": "La fenêtre, ses panneaux et les en-têtes posés dessus — les barres d’onglets des sous-fenêtres et les en-têtes du panneau de fichiers, qui partagent une seconde surface. La barre du haut de l’application suit --bg-header d’ici jusqu’à ce que vous lui donniez un fond propre dans « Barre du haut », plus bas.",
  "theme.group.topframe": "Barre du haut",
  "theme.group.topframe.help": "La barre de titre d’Eldrun — le bandeau qui porte l’horloge, les pastilles de projet et les boutons de fenêtre. Trois couches la composent : un fond, un voile d’accent par-dessus, et la couture en dessous qui dit où s’arrête le chrome de l’application et où commence son contenu. Chacune suit un token partagé tant que vous ne la fixez pas : la barre se retonalise sans que l’accent bouge dans tout le reste de la fenêtre. Les trois niveaux de texte ci-dessous sont réaffectés à tout le sous-arbre de la barre : une valeur déplace d’un coup chacun de ses libellés — les menus qui en sortent gardent l’encre du thème.",
  "theme.group.subwindow": "Sous-fenêtres",
  "theme.group.subwindow.help": "L’en-tête propre d’une sous-fenêtre — la barre d’onglets au-dessus de chaque volet — plus les deux repères qui disent quelle sous-fenêtre a le focus. La barre partage la seconde surface de chrome de l’application avec tous les en-têtes du panneau de fichiers, et ses repères lisent l’accent nu : rien de tout cela ne pouvait bouger séparément. Fixez ici un niveau de texte et toute la barre suit : libellés d’onglets, poignée, chevrons, pastilles.",
  "theme.group.sidepanel": "Panneau latéral",
  "theme.group.sidepanel.help": "Le panneau de fichiers qui glisse depuis le bord, à lui seul. Chaque valeur ici suit le jeton partagé qu’elle lirait autrement : le panneau ne se détache du reste de la fenêtre qu’une fois que vous en fixez un — et ses en-têtes bougent sans emmener les barres d’onglets des sous-fenêtres.",
  "theme.group.alerts": "Bandeau d’alertes",
