  "settings.terminalWebgl": "Rendu WebGL du terminal",
  "settings.terminalWebglHelp": "Dessine les terminaux avec un atlas de glyphes GPU (le niveau rapide — celui de VS Code) au lieu du rendu canvas. Il emprunte le même chemin de pilote GPU défaillant sur certaines machines : en cas de scintillement, de texte manquant ou de fenêtre plantée, désactivez-le. Un terminal dont le contexte WebGL échoue revient de lui-même au rendu canvas. S'applique immédiatement aux terminaux déjà ouverts.",
  "settings.mdGraph": "Graphe de liens Markdown",
  "settings.mdGraphHelp": "Ajoute un mode Graphe à la visionneuse markdown : une carte cliquable des fichiers que ce document relie, parcourue lien par lien depuis le fichier affiché (les cibles markdown sont suivies, tout autre fichier est une feuille). Cliquez sur un nœud pour ouvrir ce fichier ; la carte est construite une fois par consultation, jamais en arrière-plan.",
  "settings.pythonRunDebug": "Exécuter/Déboguer Python dans la visionneuse de code",
  "settings.mailClient": "Client de messagerie",
  "settings.mailClientHelp": "Place un bouton ✉ dans l'en-tête qui ouvre un client IMAP/SMTP, doté de son propre index local, en surimpression sur toute la fenêtre — le courrier vous appartient, pas à un projet, il n'y a donc pas d'onglet Courrier. Une pastille rouge sur le bouton compte les messages non lus de votre boîte de réception. Le désactiver retire le bouton ; vos comptes et les messages téléchargés restent intacts.",
  "settings.mailCheckInterval": "Rechercher le nouveau courrier",
