  "nav.updates.blurb": "Chercher un Eldrun plus récent sur GitHub et l’installer.",
  "updates.help": "Eldrun consulte la page des releases GitHub du projet — uniquement quand tu le demandes. Rien n’est téléchargé avant un clic, et le redémarrage reste le tien.",
  "updates.installedVersion": "Version installée",
  "updates.checking": "Vérification…",
  "updates.checkNow": "Vérifier maintenant",
  "updates.upToDate": "Eldrun est à jour.",
  "updates.versionAvailable": "La version {version} est disponible",
  "updates.noAssetForPlatform": "Cette release ne publie aucun téléchargement pour ta plateforme. Ouvre la page de la release pour voir ce qu’elle contient.",
  "updates.downloading": "Téléchargement…",
  "updates.downloadingPercent": "Téléchargement… {percent} %",
  "updates.download": "Télécharger ({size})",
  "updates.downloaded": "{name} téléchargé ({size}).",
