  "filetypes.extPlaceholder": ".ext",
  "filetypes.appPlaceholder": "commande de l'application",
  "filetypes.browseTitle": "Choisir une application",

  "remoteHosts.help":
    "Le dossier dans lequel une connexion ou un parcours s'ouvre pour un hôte SSH donné, au lieu du répertoire personnel de l'hôte. Défini une fois ici, il s'applique la prochaine fois que vous vous connectez à cet hôte — pour l'explorateur de dossiers d'un nouveau projet distant et pour la reconnexion d'un projet existant.",
  "remoteHosts.empty": "Aucun chemin standard défini — les hôtes utilisent par défaut leur répertoire personnel.",
