  "pill.vmEgressProxyCaveat": "La VM n'atteint que les hôtes ci-dessous via le proxy d'Eldrun ; tout le reste est bloqué et journalisé. Limite honnête : un agent peut encore envoyer des données vers les points autorisés (p. ex. dans un prompt) — le proxy rétrécit le canal, il ne peut pas le fermer. Les changements de mode s'appliquent au prochain démarrage.",
  "pill.vmEgressOffNote": "Sans sortie réseau la VM n'atteint rien — les onglets d'agents cloud ne fonctionnent pas ; utilisez un modèle local ou une isolation pure de build/test.",
