  "savePassword.titleTerminal": "Une connexion par terminal est quelque chose qu'Eldrun ne voit jamais, donc rien de nouveau n'est enregistré — et rien n'est supprimé non plus. Tout mot de passe déjà enregistré pour cet hôte reste inchangé.",
  "savePassword.saveFailedLabel": "Non enregistré :",
  "savePassword.lockedBannerPost": ", donc un mot de passe SSH enregistré ne peut pas être lu — cette connexion le redemandera, et Eldrun ne peut pas vous dire si un mot de passe est déjà enregistré.",
  "savePassword.unavailableBanner": "Aucun trousseau d'identifiants système n'est disponible sur cette machine, donc les mots de passe SSH ne peuvent y être ni enregistrés ni lus.",
  "autoConnect.offWhileHpc": "— désactivé tant qu'elle est étiquetée HPC",
  "autoConnect.hpcTitle": "Cette machine est étiquetée comme nœud de connexion d'un cluster HPC, donc Eldrun ne s'y connecte jamais d'elle-même. Retirez l'étiquette pour activer ceci.",
