  "machines.retryAllAria": "Tout réessayer",
  "machines.retryAllTitle": "Tout réessayer — connecte chaque machine qui n'est pas déjà connectée. Les machines étiquetées comme nœuds de connexion de cluster sont exclues ; connectez-les depuis leur propre ligne. Un hôte qui nécessite un mot de passe que nous n'avons pas reste en rouge pour être retenté depuis sa ligne.",
  "machines.disconnectAllAria": "Tout déconnecter",
  "machines.disconnectAllTitle": "Tout déconnecter — déconnecte activement chaque machine connectée : termine tous ses jobs tmux et ferme chaque connexion SSH. Les jobs ne sont terminés qu'à ce clic — jamais lors d'un redémarrage d'Eldrun.",
  "machines.usageAria": "Utilisation de l'hôte distant",
