  "machines.editTitle": "Modifie l'hôte, le nom d'utilisateur, le mot de passe ou l'étiquette de cette machine.",
  "machines.removeAria": "Supprimer la machine",
  "machines.removeTitle": "Supprime cette machine de la liste — la déconnectant d'abord activement (et terminant ses jobs tmux) si elle est connectée.",
